using Microsoft.AspNetCore.Identity;
using System.ComponentModel.DataAnnotations;
namespace Identity.Models
{
public class AppUser : IdentityUser
{
public Country Country { get ; set ; }
public int Age { get ; set ; }
[Required]
public string Salary { get ; set ; }
}
}

namespace Identity.Models
{
public enum Country
{
USA, UK, France, Germany, Russia
}
}

using System.ComponentModel.DataAnnotations;
namespace Identity.Models
{
public class User
{
[Required]
public string Name { get ; set ; }
[Required]
[RegularExpression( "^[a-zA-Z0-9_\\.-]+@([a-zA-Z0-9-]+\\.)+[a-zA-Z]{2,6}$" , ErrorMessage = "E-mail is not valid" )]
public string Email { get ; set ; }
[Required]
public string Password { get ; set ; }
public Country Country { get ; set ; }
public int Age { get ; set ; }
[Required]
public string Salary { get ; set ; }
}
}

[HttpPost]
public async Task<IActionResult> Create(User user)
{
if (ModelState.IsValid)
{
AppUser appUser = new AppUser
{
UserName = user.Name,
Email = user.Email,
Country = user.Country,
Age = user.Age,
Salary = user.Salary
};
IdentityResult result = await userManager.CreateAsync(appUser, user.Password);
if (result.Succeeded)
return RedirectToAction( "Index" );
else
{
foreach (IdentityError error in result.Errors)
ModelState.AddModelError( "" , error.Description);
}
}
return View(user);
}

[HttpPost]
public async Task<IActionResult> Update( string id, string email, string password, int age, string country, string salary)
{
AppUser user = await userManager.FindByIdAsync(id);
if (user != null )
{
if (! string .IsNullOrEmpty(email))
user.Email = email;
else
ModelState.AddModelError( "" , "Email cannot be empty" );
if (! string .IsNullOrEmpty(password))
user.PasswordHash = passwordHasher.HashPassword(user, password);
else
ModelState.AddModelError( "" , "Password cannot be empty" );
user.Age = age;
Country myCountry;
Enum.TryParse(country, out myCountry);
user.Country = myCountry;
if (! string .IsNullOrEmpty(salary))
user.Salary = salary;
else
ModelState.AddModelError( "" , "Salary cannot be empty" );
if (! string .IsNullOrEmpty(email) && ! string .IsNullOrEmpty(password) && ! string .IsNullOrEmpty(salary))
{
IdentityResult result = await userManager.UpdateAsync(user);
if (result.Succeeded)
return RedirectToAction( "Index" );
else
Errors(result);
}
}
else
ModelState.AddModelError( "" , "User Not Found" );
return View(user);
}
